"""Metric primitives. No model results are generated by this module.

PPL is exp(total NLL / valid target tokens), never an average of batch PPL.
Bootstrap inference is conditional on the supplied paired units and seeds;
the caller must supply real independent document IDs or disclose block units.
"""
from __future__ import annotations

import math
import numpy as np


def ppl_from_nll(nll_sums, token_counts):
    nll = np.asarray(nll_sums, dtype=np.float64)
    counts = np.asarray(token_counts, dtype=np.float64)
    if nll.shape != counts.shape or nll.size == 0:
        raise ValueError("NLL and token counts must have the same non-empty shape")
    if not np.isfinite(nll).all() or not np.isfinite(counts).all():
        raise ValueError("Non-finite NLL/counts cannot form a result")
    if (nll < 0).any() or (counts <= 0).any() or (counts != np.floor(counts)).any():
        raise ValueError("NLL must be nonnegative; token counts positive integers")
    mean_nll = float(nll.sum() / counts.sum())
    return {"nll_per_token": mean_nll, "ppl": math.exp(mean_nll),
            "valid_tokens": int(counts.sum())}


def paired_nll_bootstrap(base_nll_sums, new_nll_sums, token_counts,
                         document_ids, *, repetitions=10000, seed=20261115):
    """Paired two-axis bootstrap over calibration seeds and documents.

    NLL arrays have shape (calibration seeds, evaluation blocks).
    Counts have either that shape or shape (blocks,). All methods must use
    exactly the same evaluated blocks and token masks. Block-to-document IDs
    prevent treating correlated blocks/tokens as independent evidence.
    This computes one model x dataset cell, not a post-hoc selected pooled test.
    """
    base = np.asarray(base_nll_sums, dtype=np.float64)
    new = np.asarray(new_nll_sums, dtype=np.float64)
    counts = np.asarray(token_counts, dtype=np.float64)
    if base.ndim != 2 or base.shape != new.shape or not base.size:
        raise ValueError("Paired NLL arrays must be non-empty and shape (seeds, blocks)")
    if counts.shape == (base.shape[1],):
        counts = np.broadcast_to(counts, base.shape).copy()
    if counts.shape != base.shape:
        raise ValueError("Token-count shape mismatch")
    if len(document_ids) != base.shape[1] or any(x is None for x in document_ids):
        raise ValueError("One nonmissing document/block-cluster ID is required per block")
    if repetitions < 100:
        raise ValueError("Use at least 100 resamples; formal analysis defaults to 10000")
    for row, count in zip(base, counts):
        ppl_from_nll(row, count)
    for row, count in zip(new, counts):
        ppl_from_nll(row, count)
    groups = list(dict.fromkeys(document_ids))
    if len(groups) < 2:
        raise ValueError("At least two document clusters are required")
    grouped_b = np.zeros((base.shape[0], len(groups)))
    grouped_n = np.zeros_like(grouped_b)
    grouped_c = np.zeros_like(grouped_b)
    for j, g in enumerate(groups):
        mask = np.array([v == g for v in document_ids], dtype=bool)
        grouped_b[:, j] = base[:, mask].sum(axis=1)
        grouped_n[:, j] = new[:, mask].sum(axis=1)
        grouped_c[:, j] = counts[:, mask].sum(axis=1)
    per_seed = ((grouped_n.sum(axis=1) - grouped_b.sum(axis=1)) /
                grouped_c.sum(axis=1))
    rng = np.random.default_rng(seed)
    draws = np.empty(repetitions)
    for r in range(repetitions):
        si = rng.integers(0, base.shape[0], size=base.shape[0])
        di = rng.integers(0, len(groups), size=len(groups))
        delta = ((grouped_n[np.ix_(si, di)].sum(axis=1) -
                  grouped_b[np.ix_(si, di)].sum(axis=1)) /
                 grouped_c[np.ix_(si, di)].sum(axis=1))
        draws[r] = delta.mean()
    low, high = np.quantile(draws, [0.025, 0.975])
    delta = float(per_seed.mean())
    return {
        "unit": "nats_per_token", "delta_new_minus_base": delta,
        "ci95_low": float(low), "ci95_high": float(high),
        "ppl_regression_pct": 100 * math.expm1(delta),
        "ppl_gain_pct": 100 * (1 - math.exp(delta)),
        "per_seed_delta": per_seed.tolist(), "calibration_seeds": base.shape[0],
        "document_clusters": len(groups), "repetitions": repetitions,
        "bootstrap_seed": seed,
        "scope": "one_model_one_dataset_paired_seed_and_document_bootstrap",
        "caution": "Few calibration seeds give limited uncertainty information; no automatic paper gate.",
    }
